import{_ as t,o as s,c as n,a0 as e}from"./chunks/framework.UHt1LHnn.js";const u=JSON.parse('{"title":"CHAPTER 4. MCP Jira 연동 — 티켓 관리를 명령어 하나로","description":"","frontmatter":{},"headers":[],"relativePath":"ch4.md","filePath":"ch4.md"}'),i={name:"ch4.md"};function l(d,a,o,r,p,c){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="chapter-4-mcp-jira-연동-—-티켓-관리를-명령어-하나로" tabindex="-1">CHAPTER 4. MCP Jira 연동 — 티켓 관리를 명령어 하나로 <a class="header-anchor" href="#chapter-4-mcp-jira-연동-—-티켓-관리를-명령어-하나로" aria-label="Permalink to &quot;CHAPTER 4. MCP Jira 연동 — 티켓 관리를 명령어 하나로&quot;">​</a></h1><blockquote><p>Jira 열지 않고 Claude Code로 티켓을 만든다</p></blockquote><h2 id="🎫-jira-mcp-연동-방법" tabindex="-1">🎫 Jira MCP 연동 방법 <a class="header-anchor" href="#🎫-jira-mcp-연동-방법" aria-label="Permalink to &quot;🎫 Jira MCP 연동 방법&quot;">​</a></h2><p>Jira MCP는 CHAPTER 3에서 설정한 <code>mcp-atlassian</code> 서버와 동일합니다. Confluence와 Jira가 하나의 MCP 서버로 함께 연동되므로, <strong>별도 추가 설정 없이 바로 사용 가능</strong>합니다.</p><div class="tip custom-block"><p class="custom-block-title">💡 Jira 연동 전 확인 사항</p><ul><li><code>~/.claude.json</code> 에 <code>JIRA_URL</code> 및 <code>JIRA_PERSONAL_TOKEN</code> 설정 완료 여부 확인</li><li><code>JIRA_SSL_VERIFY: &quot;false&quot;</code> 설정 여부 확인 (사내망 필수)</li><li>GlobalProtect VPN 연결 상태 확인</li><li>Jira Personal Access Token은 Confluence와 <strong>별도</strong>로 발급 필요</li></ul></div><h3 id="jira-personal-access-token-발급" tabindex="-1">Jira Personal Access Token 발급 <a class="header-anchor" href="#jira-personal-access-token-발급" aria-label="Permalink to &quot;Jira Personal Access Token 발급&quot;">​</a></h3><ol><li>Jira 웹(<code>https://jira.daumkakao.com</code>) 접속</li><li>우측 상단 프로필 → <strong>Profile</strong></li><li>좌측 메뉴 <strong>Personal Access Tokens</strong> → 새 토큰 생성 후 복사</li><li><code>~/.claude.json</code> 의 <code>JIRA_PERSONAL_TOKEN</code> 값에 붙여넣기</li></ol><h2 id="⚡-티켓-생성·조회·상태-변경-실전-예시" tabindex="-1">⚡ 티켓 생성·조회·상태 변경 실전 예시 <a class="header-anchor" href="#⚡-티켓-생성·조회·상태-변경-실전-예시" aria-label="Permalink to &quot;⚡ 티켓 생성·조회·상태 변경 실전 예시&quot;">​</a></h2><p>Jira MCP 연동 후 가장 많이 사용한 기능은 <strong>티켓 생성</strong>과 <strong>상태 변경</strong>입니다. 기존에 Jira UI를 열어 직접 입력하던 작업을 Claude Code 프롬프트 한 줄로 처리할 수 있습니다.</p><h3 id="티켓-생성" tabindex="-1">티켓 생성 <a class="header-anchor" href="#티켓-생성" aria-label="Permalink to &quot;티켓 생성&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KEP 프로젝트에 아래 내용으로 Jira 티켓을 생성해줘.</span></span>
<span class="line"><span>- 제목: [Analytics] PubSub 연동 API 스펙 검토</span></span>
<span class="line"><span>- 유형: Task</span></span>
<span class="line"><span>- 담당자: chloe.sl</span></span>
<span class="line"><span>- 우선순위: High</span></span>
<span class="line"><span>- 설명: PubSub 서비스 연동을 위한 API 스펙 검토 및 기획서 작성</span></span></code></pre></div><h3 id="티켓-조회" tabindex="-1">티켓 조회 <a class="header-anchor" href="#티켓-조회" aria-label="Permalink to &quot;티켓 조회&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 내 담당 티켓 조회</span></span>
<span class="line"><span>나에게 할당된 In Progress 상태의 티켓 목록을 보여줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 특정 이슈 조회</span></span>
<span class="line"><span>KEP-1234 티켓의 상세 내용과 현재 상태를 알려줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 프로젝트 전체 조회</span></span>
<span class="line"><span>KEP 프로젝트에서 이번 주 생성된 티켓 목록을 보여줘.</span></span></code></pre></div><h3 id="티켓-상태-변경-및-코멘트-추가" tabindex="-1">티켓 상태 변경 및 코멘트 추가 <a class="header-anchor" href="#티켓-상태-변경-및-코멘트-추가" aria-label="Permalink to &quot;티켓 상태 변경 및 코멘트 추가&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 상태 변경</span></span>
<span class="line"><span>KEP-1234 티켓 상태를 &#39;In Review&#39;로 변경해줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 코멘트 추가</span></span>
<span class="line"><span>KEP-1234에 아래 내용으로 코멘트 추가해줘:</span></span>
<span class="line"><span>&quot;API 스펙 검토 완료. 기획서 초안 작성 시작 예정.&quot;</span></span></code></pre></div><h2 id="🔄-기획자가-jira를-더-잘-쓰게-된-이유" tabindex="-1">🔄 기획자가 Jira를 더 잘 쓰게 된 이유 <a class="header-anchor" href="#🔄-기획자가-jira를-더-잘-쓰게-된-이유" aria-label="Permalink to &quot;🔄 기획자가 Jira를 더 잘 쓰게 된 이유&quot;">​</a></h2><p>단순히 티켓을 빠르게 만드는 것 이상으로, Claude Code + Jira MCP 조합은 기획자의 <strong>업무 흐름 자체를 바꿨습니다.</strong></p><table tabindex="0"><thead><tr><th>상황</th><th>기존 방식</th><th>Claude Code 방식</th></tr></thead><tbody><tr><td>회의 후 액션 아이템 등록</td><td>Jira 열고 하나씩 수동 입력</td><td>회의록 메모 → 티켓 일괄 생성 요청</td></tr><tr><td>스프린트 현황 파악</td><td>Jira 보드 직접 확인</td><td>&quot;이번 스프린트 진행 현황 요약해줘&quot;</td></tr><tr><td>티켓 상태 일괄 업데이트</td><td>티켓마다 개별 클릭</td><td>&quot;완료된 항목 목록을 Done으로 변경해줘&quot;</td></tr><tr><td>특정 담당자 티켓 파악</td><td>필터 설정 후 조회</td><td>&quot;OOO 담당 미완료 티켓 목록 보여줘&quot;</td></tr></tbody></table><h2 id="⏱️-도입-전후-jira-업무-시간-비교" tabindex="-1">⏱️ 도입 전후 Jira 업무 시간 비교 <a class="header-anchor" href="#⏱️-도입-전후-jira-업무-시간-비교" aria-label="Permalink to &quot;⏱️ 도입 전후 Jira 업무 시간 비교&quot;">​</a></h2><table tabindex="0"><thead><tr><th>작업</th><th>도입 전</th><th>도입 후</th><th>단축 효과</th></tr></thead><tbody><tr><td>티켓 생성 (1건)</td><td>약 5분</td><td>약 30초</td><td><strong>90% ↓</strong></td></tr><tr><td>액션 아이템 일괄 등록</td><td>약 20분</td><td>약 3분</td><td><strong>85% ↓</strong></td></tr><tr><td>스프린트 현황 파악</td><td>약 10분</td><td>약 1분</td><td><strong>90% ↓</strong></td></tr><tr><td>상태 일괄 업데이트</td><td>약 15분</td><td>약 2분</td><td><strong>87% ↓</strong></td></tr></tbody></table><h2 id="🚨-트러블슈팅-—-atlassian-mcp-연결-오류" tabindex="-1">🚨 트러블슈팅 — Atlassian MCP 연결 오류 <a class="header-anchor" href="#🚨-트러블슈팅-—-atlassian-mcp-연결-오류" aria-label="Permalink to &quot;🚨 트러블슈팅 — Atlassian MCP 연결 오류&quot;">​</a></h2><h3 id="atlassian-상태가-fail-로-표시될-때" tabindex="-1">Atlassian 상태가 &#39;fail&#39;로 표시될 때 <a class="header-anchor" href="#atlassian-상태가-fail-로-표시될-때" aria-label="Permalink to &quot;Atlassian 상태가 &#39;fail&#39;로 표시될 때&quot;">​</a></h3><p>Claude Code → 설정 → 개발자 → Atlassian 상태가 <strong>fail</strong>로 표시된다면 아래 순서로 확인하세요.</p><div class="tip custom-block"><p class="custom-block-title">📌 참고 사항 — MCP fail 상태 원인과 해결</p><p><strong>1단계 — Docker 실행 상태 확인</strong></p><p>Claude Code의 MCP 서버들은 대부분 아래 구조로 동작합니다.</p><ul><li>Docker 기반</li><li>stdio transport 기반</li><li>Claude 실행 시 자동 spawn</li></ul><p>Docker가 죽으면 MCP도 함께 <code>Server disconnected</code> 형태로 떨어지는 경우가 많습니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Docker 실행 중인 컨테이너 확인</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Docker 데몬이 실행 중인지 확인</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span></code></pre></div></div><table tabindex="0"><thead><tr><th>증상</th><th>원인</th><th>해결 방법</th></tr></thead><tbody><tr><td>Atlassian 상태 <strong>fail</strong></td><td>Docker 데몬 미실행</td><td>Docker Desktop 실행 후 Claude Code 재시작</td></tr><tr><td><code>Server disconnected</code></td><td>Docker 컨테이너 종료</td><td>Docker 재실행 후 Claude Code 재시작</td></tr><tr><td>MCP 응답 없음</td><td>VPN 미연결</td><td>GlobalProtect VPN 연결 후 재시도</td></tr><tr><td>간헐적 연결 끊김</td><td>Docker 메모리 부족</td><td>불필요한 컨테이너 정리 후 재시작</td></tr></tbody></table><blockquote><p>⚠️ MCP 설정을 변경한 경우 반드시 <strong>Claude Code를 완전히 종료 후 재시작</strong>해야 새 설정이 반영됩니다. 단순 새로고침으로는 적용되지 않습니다.</p></blockquote><p>Jira와 Confluence는 동일한 <code>mcp-atlassian</code> 서버를 공유하므로, Atlassian MCP가 정상 동작하면 두 서비스 모두 함께 사용할 수 있습니다. 다음 <strong>CH.5</strong>에서는 Figma MCP 연동을 통해 기획 화면 시안을 직접 만드는 방법을 다룹니다.</p>`,27)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
